def add_batch(
    cmd: commands.CreateBatch,
    uow: unit_of_work.AbstractUnitOfWork,
):
    if cmd.expiry is not None and not isinstance(cmd.expiry, date):
        raise InvalidExpiry(f"Batch {cmd.ref}: expiry {cmd.expiry!r} is not a date")
    if cmd.expiry is not None and cmd.eta is not None and cmd.expiry < cmd.eta:
        raise InvalidExpiry(f"Batch {cmd.ref}: expiry {cmd.expiry} is earlier than eta {cmd.eta}")
    with uow:
        product = uow.products.get(sku=cmd.sku)
        if product is None:
            product = model.Product(cmd.sku, batches=[])
            uow.products.add(product)
        product.batches.append(model.Batch(cmd.ref, cmd.sku, cmd.qty, cmd.eta, cmd.expiry))
        uow.commit()
